params={}
for line in source.splitlines():
    m=re.match(r'^\| `([a-z_]+)` \| (.+?) \|$',line)
    if m: params[m[1]]=m[2].replace('&#124;','|')
rows=[]
for line in source.splitlines():
    m=re.match(r'^\| `/([^`]+)` \| (.*?) \| ((?:`.*?`(?: · )?)+|—) \| ([^|]+) \|$',line)
    if not m: continue
    name,description,raw,perm=m.groups()
    category='welcome' if name.startswith('welcome ') else 'automod' if name.startswith('automod ') else 'events' if name.startswith('giveaway ') or name in EVENTS else 'afk' if name in AFK else 'invites' if name in INVITES else 'moderation' if name in MOD else 'fun' if name in FUN else 'community' if name in COMMUNITY else 'utility'
    parameters=[]
    for p in re.findall(r'`([^`]+)`',raw):
        optional=p.startswith('[')
        p=p.strip('[]')
        parameters.append({'name':p,'required':not optional,'es':params[p],'en':PEN[p]})
    access,pen=PERMS[perm]
    example=EXAMPLES.get(name,'/'+name)
    exen=example.replace('Estudiando','Studying').replace('#anuncios','#announcements').replace('#sorteos','#giveaways').replace('#invitaciones','#invites').replace('#sugerencias','#suggestions').replace('#bienvenidas','#welcome').replace('#despedidas','#farewells').replace('@Textureros','@TextureArtists').replace('¿Qué evento hacemos?','Which event should we host?').replace('Organizar un torneo semanal','Host a weekly tournament').replace('¡Bienvenido/a, {user}! Ya somos {count} en {server}.','Welcome, {user}! There are now {count} members in {server}.').replace('Bienvenido/a, {user}, a FM Society.','Welcome to FM Society, {user}.').replace('expresión bloqueada','blocked phrase').replace('Incumplimiento de las reglas','Breaking the rules').replace('Apelación aceptada','Appeal accepted').replace('¿Ganaremos el torneo?','Will we win the tournament?').replace('Revisar las sugerencias','Review suggestions')
    row={'name':name,'category':category,'es':description.rstrip('.'),'en':EN[name],'parameters':parameters,'permission':{'es':perm,'en':pen,'access':access},'example':{'es':example,'en':exen}}
    if name in NOTES: row['note']={'es':NOTES[name][0],'en':NOTES[name][1]}
    rows.append(row)
assert len(rows)==71, len(rows)
assert len({r['name'] for r in rows})==71
assert set(EN)=={r['name'] for r in rows}
(ROOT/'catalog.js').write_text('window.FM_CATALOG = '+json.dumps(rows,ensure_ascii=False,separators=(',',':'))+';\n')
print(f'Catalog generated: {len(rows)} commands, {sum(len(r["parameters"]) for r in rows)} documented parameters, ES/EN.')
